import json, re

def _parse(raw):
    raw = re.sub(r'^```(?:json)?\s*|\s*```$', '', raw.strip())
    d = json.loads(raw)
    if not (isinstance(d, dict) and isinstance(d.get('sender'), str)):
        raise ValueError('missing sender')
    return d

def extract(call_model, prompt):
    msgs = [{'role': 'user', 'content': prompt}]
    raw = call_model(msgs)
    try:
        return _parse(raw)
    except ValueError as e:
        msgs = msgs + [{'role': 'assistant', 'content': raw}, {'role': 'user', 'content': f'Fix your answer: return only JSON. Error: {e}'}]
    return _parse(call_model(msgs))

