ex.sol:
def run_tool(call, registry):
    fn = registry.get(call['name'])
    if fn is None:
        return {'tool_use_id': call['id'], 'content': f"Unknown tool {call['name']}", 'is_error': True}
    try:
        return {'tool_use_id': call['id'], 'content': str(fn(**call['input']))}
    except Exception as e:
        return {'tool_use_id': call['id'], 'content': f'Tool failed: {e}', 'is_error': True}
